// Stripe reports amounts in the smallest currency unit — but not every currency
// has 100 of them. JPY, KRW and 13 others are zero-decimal, so the reflexive
// `amount / 100` issues an invoice 100x too small. Check before dividing.
const ZERO_DECIMAL = ['bif', 'clp', 'djf', 'gnf', 'jpy', 'kmf', 'krw', 'mga', 'pyg', 'rwf', 'ugx', 'vnd', 'vuv', 'xaf', 'xof', 'xpf'];

const cfg = $('Set Invoice Defaults').first().json;
// The Stripe Trigger emits the Event envelope, not the PaymentIntent —
// the object itself is nested at data.object.
const payment = $('Payment Succeeded').first().json.data.object;
const customer = $input.first().json || {};

const currency = (payment.currency || 'usd').toLowerCase();
const zeroDecimal = ZERO_DECIMAL.includes(currency);
const decimals = zeroDecimal ? 0 : 2;
const round = (v) => Number(v.toFixed(decimals));

const total = round((payment.amount_received || payment.amount || 0) / (zeroDecimal ? 1 : 100));

// If a tax rate is set, derive the net so the invoice shows net + tax. Note the
// limit: PDFops recomputes subtotal -> tax -> total from unit_price, and roughly
// 10% of (amount, rate) pairs have NO 2-decimal net that multiplies back to the
// exact charged total — it is a representability limit, not a rounding bug.
// Leave taxRate at 0 (the default) if you need the invoice total to equal the
// charge exactly; the sticky says so too.
const rate = Number(cfg.taxRate) || 0;
const unitPrice = round(rate > 0 ? total / (1 + rate / 100) : total);

// Guest checkouts have no customer object — fall back to the receipt email.
const billTo = customer.name || customer.email || payment.receipt_email || 'Customer';

return [
  {
    json: {
      invoice: {
        from: cfg.companyName,
        to: billTo,
        invoice_number: `${cfg.invoicePrefix}-${String(payment.id).slice(-8).toUpperCase()}`,
        date: new Date((payment.created || Date.now() / 1000) * 1000).toISOString().slice(0, 10),
        currency: currency.toUpperCase(),
        tax_rate: rate,
        notes: cfg.invoiceNotes,
        items: [
          {
            description: payment.description || cfg.defaultLineItem,
            quantity: 1,
            unit_price: unitPrice,
          },
        ],
      },
      customerEmail: customer.email || payment.receipt_email || '',
      paymentId: payment.id,
      chargedTotal: total,
      s3Bucket: cfg.s3Bucket,
    },
  },
];
